"""Ten letters, written for ten distinct briefs rather than substituted topics."""
from exam_common import case, p, coverage as c
G = 'writing-task1'

def samples():
    return [
case(G, 'visiting-parents', 'Tư vấn chuyến thăm của bố mẹ người bạn', 'Accommodation, sightseeing and vegetarian food', 'reply', 'Trả lời thông tin cho bạn',
    "Richard's parents will visit your hometown, arriving Tuesday 16th at 18:05 and leaving Monday 22nd at 14:45. Recommend a hotel; cover its sightseeing trips, room cost, breakfast inclusion and vegetarian restaurant dishes. Reply by email (120+ words).",
    ['Trả lời đủ: nơi ở, giá phòng, bữa sáng, tham quan, món chay.', 'Lịch gợi ý phải phù hợp giờ đến và rời đi.', 'Viết thân mật cho Richard; thông tin dịch vụ trong bài là giả định để luyện.'], [
        p('Chào và giới thiệu nơi ở', "Hi Richard,\n\nThanks for your message. I'd be happy to help your parents plan their visit. I would recommend Green Garden Hotel near the town centre. It has a lift and is only a short walk from the river, so they would not need to take taxis everywhere.", 'Tên khách sạn là chi tiết tự đặt, không phải thông tin đặt phòng thật.'),
        p('Giá và ăn uống', "A double room costs about 700,000 dong per night, including breakfast for two. Its restaurant serves vegetarian dishes, including vegetable noodles and tofu with rice. They should mention their diet when booking so the kitchen can prepare food without meat or fish sauce.", 'Trả lời riêng giá, bữa sáng và món chay; không bỏ sót câu hỏi nhỏ.'),
        p('Lịch trình và lời kết', "As they arrive on Tuesday evening, I'd suggest a quiet dinner first. The hotel arranges day trips to the local museum and a nearby village. They could join one on Wednesday and explore the riverside later in the week. They should keep Monday morning free to pack and leave for the airport.\n\nPlease let me know if they need help booking a room.\n\nBest wishes,", 'Gắn gợi ý với thời điểm đến và về; không xếp tour vào giờ ra sân bay.')],
    [('a double room','phòng đôi'), ('including breakfast','bao gồm bữa sáng'), ('fish sauce','nước mắm')], source='dthu', page=18, register='informal',
    checks=[c('Gợi ý chỗ ở','Green Garden Hotel'),c('Giá phòng','700,000 dong per night'),c('Có bữa sáng không?','including breakfast for two'),c('Nhà hàng có món chay','restaurant serves vegetarian dishes'),c('Tour từ khách sạn','hotel arranges day trips'),c('Ngày về','keep Monday morning free')]),
case(G, 'introduce-houseguest', 'Giới thiệu người bạn sẽ ở nhờ', 'Personality, interests and current studies', 'reply', 'Trả lời thông tin cho bạn',
    "Jane may host your friend An while An attends a summer course in London and looks for a flat. Tell Jane about An's character, interests and current occupation or studies. Write a friendly reply (120+ words).",
    ['Giới thiệu tính cách bằng biểu hiện cụ thể.', 'Nêu sở thích và việc học hoặc công việc hiện tại.', 'Giúp Jane hình dung việc sống chung; không tự chuyển thành thư xin ở nhờ.'], [
        p('Lý do trả lời', "Hi Jane,\n\nThank you for your email. I'm glad you're considering letting An stay with your family. We've been friends since secondary school, so I know her quite well and think you would get along.", 'Người viết giới thiệu bạn mình, không đóng vai An.'),
        p('Tính cách và sở thích', "An is friendly and considerate. When we shared a room on a college trip, she always kept her things tidy and asked before borrowing anything. She may seem a little quiet at first, but she becomes talkative once she knows people. As for her interests, she enjoys cooking Vietnamese dishes and cycling. I'm sure she'd be happy to cook a meal for your family.", 'Hai nét tính cách có ví dụ; sở thích không chỉ là tính từ chung.'),
        p('Việc học và kết', "She's currently studying business at university and works at a small bookshop on Saturdays. The London course will help her improve her English before her final year. She usually studies in the evening, so she is unlikely to disturb anyone with loud music.\n\nPlease let me know if you'd like to ask anything else about her.\n\nBest wishes,", 'Nêu việc học hiện tại và liên hệ với sinh hoạt gia đình.')],
    [('considerate','biết quan tâm đến người khác'),('get along','hòa hợp'),('keep things tidy','giữ đồ đạc gọn gàng')], source='ufls', page=15, register='informal',
    checks=[c('Tính cách','friendly and considerate'),c('Sở thích','cooking Vietnamese dishes and cycling'),c('Hiện đang học/làm gì','studying business at university')]),
case(G, 'damaged-desk', 'Phàn nàn bàn học bị hỏng khi giao', 'Damaged furniture and a replacement request', 'complaint', 'Phàn nàn / yêu cầu xử lý',
    "You ordered a desk from Oak Home, order OH248, delivered on 4 June. Its top is cracked and one leg is missing. Email customer service: explain the faults and their impact, request a suitable remedy, and say when you can receive a delivery. Write at least 120 words.",
    ['Ghi đúng mã đơn, ngày giao và hai lỗi.', 'Nêu ảnh hưởng, yêu cầu thay thế và giờ nhận hàng.', 'Lịch sự nhưng rõ yêu cầu; không chỉ bày tỏ thất vọng.'], [
        p('Nêu đơn hàng và lỗi', "Dear Customer Service Team,\n\nI am writing to complain about a desk from order OH248, which arrived on 4 June. When I opened the box, I found a long crack across the top and noticed that one of the legs was missing. I have attached photographs of both the packaging and the damaged parts.", 'Có thông tin để bên bán tra cứu và bằng chứng dự kiến gửi.'),
        p('Ảnh hưởng và cách giải quyết', "The desk cannot be assembled safely, so I am unable to use it for my online classes. I would like to receive a replacement rather than a repair, as I paid for a new, complete item. Could you please arrange to collect the faulty desk when you deliver the replacement, at no additional cost to me?", 'Chọn rõ cách giải quyết, không đưa hàng loạt yêu cầu mâu thuẫn.'),
        p('Thời gian và kết', "I will be at home after 4 p.m. on weekdays and all day on Saturday. Please confirm the delivery date in advance so that I can make the necessary arrangements.\n\nI look forward to hearing from you.\n\nYours faithfully,", 'Không biết tên người nhận; kết thư trang trọng.')],
    [('a replacement','sản phẩm thay thế'),('at no additional cost','không tính thêm phí'),('in advance','trước khi việc đó diễn ra')], register='formal',
    checks=[c('Đơn và ngày giao','OH248, which arrived on 4 June'),c('Hai lỗi','one of the legs was missing'),c('Ảnh hưởng','cannot be assembled safely'),c('Cách xử lý','collect the faulty desk'),c('Giờ nhận','after 4 p.m. on weekdays')]),
case(G, 'weekend-receptionist', 'Ứng tuyển lễ tân cuối tuần', 'Relevant experience and interview availability', 'application', 'Xin việc',
    "Riverside Hostel advertises a paid weekend receptionist position. Applicants should communicate in English and use a computer. Write to Ms Tran: explain your interest, give relevant experience, and state your working hours and interview availability. Write at least 120 words.",
    ['Nêu đúng vị trí có trả lương và người nhận.', 'Chứng minh khả năng tiếng Anh, máy tính bằng việc đã làm.', 'Tách giờ làm được với giờ có thể phỏng vấn.'], [
        p('Mục đích và động lực', "Dear Ms Tran,\n\nI am writing to apply for the weekend receptionist position at Riverside Hostel. I am a second-year tourism student and would like to gain practical experience helping visitors. Your hostel is close to my university, so I could travel to work easily and arrive on time.", 'Động lực phù hợp một công việc cụ thể.'),
        p('Kinh nghiệm phù hợp', "Last summer, I worked at my aunt's guesthouse, where I welcomed guests, answered basic questions in English and recorded bookings on a computer. I also checked room payments using a spreadsheet. This experience taught me to stay calm when several guests needed help at once. Although I have not used your booking system, I am willing to learn it before starting.", 'Có dẫn chứng cho từng kỹ năng, không tự nhận thành thạo mọi phần mềm.'),
        p('Lịch và kết thư', "I am available every Saturday and Sunday from 7 a.m. to 5 p.m. During the coming week, I can attend an interview after 3 p.m. on Tuesday or Thursday. I have attached my CV for your consideration.\n\nI look forward to hearing from you.\n\nYours sincerely,", 'Giờ đi làm và giờ phỏng vấn rõ ràng; biết tên thì dùng sincerely.')],
    [('recorded bookings','ghi nhận đặt phòng'),('a spreadsheet','bảng tính'),('attend an interview','tham dự phỏng vấn')], register='formal',
    checks=[c('Vị trí','weekend receptionist position'),c('Kinh nghiệm tiếng Anh và máy tính','answered basic questions in English'),c('Giờ đi làm','every Saturday and Sunday'),c('Phỏng vấn','Tuesday or Thursday')]),
case(G, 'evening-course', 'Hỏi thông tin khóa học buổi tối', 'Timetable, fees and a placement test', 'request', 'Yêu cầu thông tin',
    "You work until 5:30 p.m. on weekdays and want to join Bright Language Centre's evening English course. Ask about lesson times, total fees, class size and placement testing. Explain your learning goal. Write a formal email of at least 120 words.",
    ['Nêu giờ tan làm và mục tiêu học.', 'Hỏi đủ lịch, tổng phí, sĩ số và kiểm tra đầu vào.', 'Không biến thư hỏi thành thư đăng ký chắc chắn.'], [
        p('Hoàn cảnh và mục tiêu', "Dear Course Coordinator,\n\nI am writing to request information about your evening English course. I work in a small travel company and would like to improve my speaking so that I can communicate more confidently with international customers. I finish work at 5:30 p.m. on weekdays, so I need a class that starts after 6 p.m.", 'Cho trung tâm điều kiện để tư vấn đúng lớp.'),
        p('Lịch, phí và sĩ số', "Could you please tell me which evenings the course runs and how long each lesson lasts? I would also like to know the total fee, including textbooks and any examination charges. As I need plenty of speaking practice, I am interested in finding out how many students normally attend each class.", 'Hỏi tổng chi phí, không chỉ học phí được quảng cáo.'),
        p('Đầu vào và kết', "Finally, do new students take a placement test before enrolling? If so, please let me know whether I can take it online and when the next course begins. This information would help me choose a class that suits my level and work schedule.\n\nYours faithfully,", 'Nối bài kiểm tra với việc chọn lớp phù hợp.')],
    [('total fee','tổng chi phí'),('placement test','bài kiểm tra xếp lớp'),('work schedule','lịch làm việc')], register='formal',
    checks=[c('Mục tiêu','international customers'),c('Lịch học','which evenings the course runs'),c('Tổng phí','including textbooks'),c('Sĩ số','how many students'),c('Đầu vào','placement test')]),
case(G, 'refund-reply', 'Trả lời khách về tiền đặt phòng', 'Cancellation policy and a practical response', 'formal-reply', 'Trả lời khách hàng',
    "You manage Lake View Guesthouse. Ms Brown cancelled six days before arrival and asks for a refund of her 500,000-dong deposit. Policy: cancellations at least five days ahead receive a full deposit refund. Reply with the decision, information needed and a processing time of three working days. Write 120+ words.",
    ['Áp dụng đúng chính sách đã cho: đủ điều kiện hoàn toàn bộ.', 'Nêu số tiền và thông tin cần để chuyển khoản.', 'Giải thích thời điểm bắt đầu tính ba ngày làm việc.'], [
        p('Xác nhận và quyết định', "Dear Ms Brown,\n\nThank you for your email. I have checked your booking and can confirm that you cancelled six days before your planned arrival. Our policy allows a full deposit refund when a guest cancels at least five days in advance, so we will return the full 500,000 dong to you.", 'Không tự bịa lý do từ chối hoặc trừ phí trái đề.'),
        p('Thông tin và thời gian', "Could you please send us the account holder's name, bank name and account number for the transfer? Please also include your booking reference so that we can match the information to the correct reservation. We will process the refund within three working days after receiving these details. Weekends and public holidays are not included in this period.", 'Trong bài thi chỉ nêu loại thông tin; không cung cấp dữ liệu ngân hàng thật.'),
        p('Hỗ trợ tiếp', "Once the payment has been sent, we will email you a confirmation. If it has not reached your account after that period, please contact us and we will check it with our bank.\n\nWe hope to welcome you on another occasion.\n\nYours sincerely,", 'Đưa bước tiếp theo nếu khách chưa nhận được tiền.')],
    [('deposit refund','hoàn tiền đặt cọc'),('booking reference','mã đặt phòng'),('working days','ngày làm việc')], register='formal',
    checks=[c('Áp dụng đúng chính sách','cancelled six days before'),c('Số tiền hoàn','full 500,000 dong'),c('Thông tin cần','account holder'),c('Mốc ba ngày','after receiving these details')]),
case(G, 'broken-camera', 'Xin lỗi vì làm hỏng máy ảnh mượn', 'Taking responsibility and arranging a repair', 'apology', 'Xin lỗi bạn',
    "You borrowed Sam's camera for a weekend trip and damaged its screen. Write to Sam: explain what happened, apologise, offer to pay for a repair and arrange to return it before Sam's family event next Saturday. Write at least 120 words.",
    ['Nhận trách nhiệm, không đổ lỗi cho người cho mượn.', 'Giải thích sự cố và đề nghị trả tiền sửa.', 'Đảm bảo có máy cho sự kiện thứ Bảy hoặc nêu phương án dự phòng.'], [
        p('Xin lỗi và kể sự cố', "Hi Sam,\n\nI am sorry that I damaged your camera during my trip last weekend. I put it on a low wall while looking for my phone, and accidentally knocked it onto the ground. The camera still takes pictures, but there is a crack across the screen. I should have kept it in its case.", 'Xin lỗi trực tiếp và nhận trách nhiệm.'),
        p('Sửa chữa và chi phí', "I know you need it for your family event next Saturday. I've contacted a repair shop, and they said they could replace the screen by Thursday if I bring it in tomorrow. I'll pay the full repair cost, of course. Could you please let me know if you're happy for me to use that shop?", 'Xin phép chủ máy trước khi sửa; mốc thời gian có ý nghĩa.'),
        p('Trả lại và dự phòng', "I can bring the camera to your house on Friday evening. If the repair takes longer than expected, I'll arrange a rental camera for your event and cover that cost too. I'm really sorry for causing you this trouble.\n\nBest wishes,", 'Có giải pháp nếu không kịp trả trước sự kiện.')],
    [('repair cost','chi phí sửa chữa'),('replace the screen','thay màn hình'),('a rental camera','máy ảnh thuê')], register='informal',
    checks=[c('Sự cố','knocked it onto the ground'),c('Xin lỗi','I am sorry'),c('Chi trả','full repair cost'),c('Trả trước thứ Bảy','Friday evening')]),
case(G, 'birthday-decline', 'Từ chối sinh nhật và hẹn dịp khác', 'A warm refusal with a concrete alternative', 'decline', 'Từ chối lời mời',
    "Your friend Mia invites you to her birthday dinner this Friday. You must take your mother to a medical appointment in another city. Thank Mia, explain why you cannot come, and suggest another time and activity to celebrate together. Write at least 120 words.",
    ['Cảm ơn lời mời và từ chối rõ ràng.', 'Giải thích ngắn đúng lý do đề cho.', 'Hẹn thời gian và hoạt động thay thế cụ thể.'], [
        p('Cảm ơn và từ chối', "Hi Mia,\n\nThanks for inviting me to your birthday dinner on Friday. It sounds like a lovely evening, and I was really looking forward to seeing everyone. Unfortunately, I won't be able to come because I need to take my mother to a medical appointment in another city that day.", 'Từ chối nhẹ nhàng nhưng không mập mờ.'),
        p('Giải thích và đề xuất', "Her appointment is in the afternoon, and we probably won't get home until late. I don't want to promise that I'll make it and then keep you waiting. Would you be free on Sunday afternoon instead? We could have lunch at the little Italian restaurant near your office and go for a walk afterwards. I'd love to hear how your birthday evening went.", 'Có ngày, thời gian tương đối và hoạt động thay thế.'),
        p('Hẹn phản hồi', "Lunch would be my treat, of course. Please let me know whether Sunday works for you, or suggest another day if you're busy. I hope you have a wonderful birthday with your family and friends.\n\nAll the best,", 'Giữ giọng thân mật; không dùng văn hành chính.')],
    [('medical appointment','lịch hẹn khám bệnh'),('my treat','tôi mời / tôi trả tiền'),('make it','đến tham dự được')], register='informal',
    checks=[c('Cảm ơn','Thanks for inviting me'),c('Lý do','take my mother'),c('Thời gian khác','Sunday afternoon'),c('Hoạt động','Italian restaurant')]),
case(G, 'host-thanks', 'Cảm ơn gia đình đã đón tiếp', 'A specific memory and a return invitation', 'thanks', 'Cảm ơn',
    "You stayed with your friend Lucy's family for a week. Write to Lucy after returning home: thank the family, describe what you enjoyed most, and invite Lucy to visit you, suggesting a time and things to do. Write at least 120 words.",
    ['Cảm ơn cả gia đình, nêu một kỷ niệm cụ thể.', 'Mời Lucy đến thăm, có thời gian và hoạt động.', 'Giữ nội dung là thư cảm ơn sau chuyến đi.'], [
        p('Đã về nhà và cảm ơn', "Hi Lucy,\n\nI've arrived home safely, and I wanted to thank you and your family for such a wonderful week. Please tell your parents how much I appreciated their kindness. Having a comfortable room and someone to talk to each evening made me feel at home straight away.", 'Một lời cảm ơn gắn với sự giúp đỡ thực tế.'),
        p('Kỷ niệm đáng nhớ', "The best part was our bicycle ride to the lake. I loved stopping at the small bakery on the way and having lunch by the water. Your father was so patient when I couldn't keep up! I also enjoyed helping your mother cook dinner and learning how she makes her vegetable soup.", 'Kỷ niệm cụ thể giúp thư tự nhiên, không dùng lời khen rỗng.'),
        p('Mời thăm lại', "I'd love you to visit me during the first week of August, when I'll be on holiday. You could stay in our spare room, and I could show you the old market and take you to the beach for a day. Please let me know what you think.\n\nBest wishes,", 'Thời gian, chỗ ở và hai hoạt động tạo lời mời khả thi.')],
    [('feel at home','cảm thấy thoải mái như ở nhà'),('keep up','theo kịp'),('spare room','phòng còn trống')], register='informal',
    checks=[c('Cảm ơn gia đình','thank you and your family'),c('Kỷ niệm','bicycle ride to the lake'),c('Mời và thời gian','first week of August'),c('Hoạt động gợi ý','old market')]),
case(G, 'office-invitation', 'Mời chuyên gia nói chuyện hướng nghiệp', 'A formal invitation with practical arrangements', 'formal-invitation', 'Mời trang trọng',
    "You organise a university careers evening on 20 September, 6–8 p.m. Invite Ms Le, a local hotel manager, to give a 20-minute talk about careers in hospitality followed by questions. Mention the audience, venue, travel support and a reply deadline of 5 September. Write 120+ words.",
    ['Mời đúng vai trò, chủ đề và thời lượng.', 'Có ngày, giờ, địa điểm và đối tượng nghe.', 'Nêu hỗ trợ đi lại và hạn trả lời; không yêu cầu làm cả buổi.'], [
        p('Lời mời và lý do', "Dear Ms Le,\n\nI am writing to invite you to speak at our university careers evening on 20 September. The event will run from 6 to 8 p.m. in Hall B on the main campus. Around sixty final-year tourism students are expected to attend, and your experience managing a local hotel would be very useful to them.", 'Đủ thời gian, nơi và đối tượng; lời mời có lý do.'),
        p('Nội dung và sắp xếp', "We would be grateful if you could give a twenty-minute talk about starting a career in hospitality, followed by ten minutes of questions. Students are especially interested in the skills employers look for and ways to prepare for a first interview. We can provide a projector and arrange a taxi to collect you and take you home afterwards.", 'Phân biệt thời lượng sự kiện với phần trình bày của khách.'),
        p('Hạn hồi âm', "Could you please confirm by 5 September whether you are available? If you need any further information or have particular equipment requirements, I would be happy to help.\n\nThank you for considering our invitation.\n\nYours sincerely,", 'Hạn phản hồi và đầu mối hỗ trợ rõ ràng.')],
    [('hospitality','ngành dịch vụ lưu trú, ăn uống'),('final-year students','sinh viên năm cuối'),('equipment requirements','yêu cầu về thiết bị')], register='formal',
    checks=[c('Ngày và giờ','20 September'),c('Địa điểm và người nghe','Hall B'),c('Thời lượng và hỏi đáp','twenty-minute talk'),c('Đi lại','arrange a taxi'),c('Hạn phản hồi','by 5 September')]),
]
